WITH x10 AS (SELECT X(x7.v192724) FROM x11 GROUP BY x7.v192724 ORDER BY CASE WHEN x7.v192724 IS NULL THEN 1 ELSE 0 END, x7.v192724) SELECT x7.v192724, x7.v192724, ST_CROSSES(IS_IPV4_MAPPED(BIN_TO_UUID(@a := 34)), ST_DIFFERENCE(ST_GEOMFROMTEXT('POLYGON((8 6,5 7,-1 4,-8 -7,0 -17,8 6),(3 6,5 5,0 -2,3 6))'), ST_GEOMFROMTEXT('POLYGON((3 5,-17 11,-8 -3,3 5))'))) AS x4, x7.v192724 FROM v192723 AS x7 WHERE x7.v192724 BETWEEN x7.v192724 AND 'KKK'